#!/usr/bin/env python3
"""Merge the vendor's translated XLIFF back into a .docx via `kapi apply`.

Usage: python3 vendor-kit/merge-return.py <translated.xliff> [out.docx]

Note: `kapi merge` cannot reconstruct .docx in kapi v1.2.0-rc29 (it writes a
0-byte file), so this routes the targets through `kapi apply`, which round-trips
correctly and enforces the inline-code guard.
"""
import json, re, shutil, subprocess, sys, xml.etree.ElementTree as ET

NS = {'x': 'urn:oasis:names:tc:xliff:document:2.1'}
SRC = 'report.docx'


def pc_to_kapi(el):
    """XLIFF <pc id="c1">t</pc>  ->  kapi <x id="c1"/>t<x id="/c1"/>"""
    parts = [el.text or '']
    for child in el:
        tag = child.tag.split('}')[-1]
        if tag == 'pc':
            cid = child.get('id')
            parts += ['<x id="%s"/>' % cid, pc_to_kapi(child), '<x id="/%s"/>' % cid]
        parts.append(child.tail or '')
    return ''.join(parts)


def main():
    xliff, out_docx = sys.argv[1], (sys.argv[2] if len(sys.argv) > 2 else 'report.fr.docx')
    targets = {}
    for unit in ET.parse(xliff).getroot().findall('.//x:unit', NS):
        tgt = unit.find('.//x:target', NS)
        if tgt is None or not ''.join(tgt.itertext()).strip():
            print('!! untranslated unit: %s' % unit.get('id'), file=sys.stderr)
            continue
        targets[unit.get('id')] = pc_to_kapi(tgt)

    shutil.copyfile(SRC, out_docx)
    blocks = [json.loads(l) for l in subprocess.run(
        ['kapi', 'inspect', out_docx, '--jsonl'],
        capture_output=True, text=True, check=True).stdout.splitlines() if l.strip()]

    edits, missing = [], []
    for b in blocks:
        if b['id'] in targets:
            edits.append(json.dumps({'kind': 'content', 'file': b['file'], 'id': b['id'],
                                     'content_hash': b['content_hash'],
                                     'text': targets[b['id']]}, ensure_ascii=False))
        else:
            missing.append(b['id'])
    if missing:
        print('!! no target for: %s' % ', '.join(missing), file=sys.stderr)

    with open('vendor-kit/.return-edits.jsonl', 'w', encoding='utf-8') as fh:
        fh.write('\n'.join(edits) + '\n')
    subprocess.run(['kapi', 'apply', 'vendor-kit/.return-edits.jsonl'], check=True)
    print('\n-> %s' % out_docx)
    sys.exit(1 if missing else 0)


if __name__ == '__main__':
    main()

