import LocaleSwitcher from "./components/LocaleSwitcher.jsx";
import { I18nProvider, useTranslation } from "./i18n/index.js";

function Dashboard() {
  const { t } = useTranslation();
  const count = 3;

  return (
    <main>
      <nav>
        <a href="/">{t("nav.dashboard")}</a>
        <a href="/tasks">{t("nav.tasks")}</a>
      </nav>
      <h1>{t("home.greeting", { name: "Alex" })}</h1>
      <p>{t("home.tasksDue", { count })}</p>
      <button>{t("actions.addTask")}</button>
      <label>
        <input type="checkbox" /> {t("settings.emailUpdates")}
      </label>
      <LocaleSwitcher />
    </main>
  );
}

export default function App() {
  return (
    <I18nProvider>
      <Dashboard />
    </I18nProvider>
  );
}

import { useId } from "react";
import { LOCALES, SUPPORTED_LOCALES, useTranslation } from "../i18n/index.js";

export default function LocaleSwitcher() {
  const { t, locale, setLocale } = useTranslation();
  const id = useId();

  return (
    <div>
      <label htmlFor={id}>{t("localeSwitcher.label")}</label>
      <select
        id={id}
        value={locale}
        onChange={(event) => setLocale(event.target.value)}
      >
        {SUPPORTED_LOCALES.map((code) => (
          // `lang` so each option is announced in its own language.
          <option key={code} value={code} lang={code}>
            {LOCALES[code].label}
          </option>
        ))}
      </select>
    </div>
  );
}

import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
