import { LOCALES, STORAGE_KEY, detectLocale, resolveLocale } from "./config.js";
import { translate } from "./translate.js";

const I18nContext = createContext(null);

export function I18nProvider({ children, locale: localeProp }) {
  // `localeProp` lets tests / SSR pin a locale; otherwise we detect once.
  const [selected, setSelected] = useState(detectLocale);
  const locale = resolveLocale(localeProp ?? selected);

  const setLocale = useCallback((next) => {
    const resolved = resolveLocale(next);
    setSelected(resolved);
    try {
      window.localStorage?.setItem(STORAGE_KEY, resolved);
    } catch {
      // Persistence is best-effort; the choice still applies for this session.
    }
  }, []);

  // Keep the document in sync so screen readers, spellcheck and CSS
  // `:dir()` selectors follow the active language.
  useEffect(() => {
    const root = document.documentElement;
    root.lang = locale;
    root.dir = LOCALES[locale].dir;
  }, [locale]);

  const value = useMemo(
    () => ({
      locale,
      setLocale,
      dir: LOCALES[locale].dir,
      t: (key, values) => translate(locale, key, values),
    }),
    [locale, setLocale],
  );

  return <I18nContext.Provider value={value}>{children}</I18nContext.Provider>;
}

export function useTranslation() {
  const context = useContext(I18nContext);
  if (!context) {
    throw new Error("useTranslation must be used within an <I18nProvider>");
  }
  return context;
}

import en from "./locales/en.js";
import es from "./locales/es.js";
import fr from "./locales/fr.js";

export const DEFAULT_LOCALE = "en";

/** Add a locale by dropping a catalog in ./locales and registering it here. */
export const LOCALES = {
  en: { label: "English", dir: "ltr", messages: en },
  es: { label: "Español", dir: "ltr", messages: es },
  fr: { label: "Français", dir: "ltr", messages: fr },
};

export const SUPPORTED_LOCALES = Object.keys(LOCALES);

export const STORAGE_KEY = "app.locale";

/** Match a language tag ("es-MX") against the supported locales, or null. */
export function matchLocale(tag) {
  if (!tag) return null;
  if (SUPPORTED_LOCALES.includes(tag)) return tag;
  const base = String(tag).split("-")[0].toLowerCase();
  return SUPPORTED_LOCALES.includes(base) ? base : null;
}

/** Like matchLocale, but always returns something renderable. */
export function resolveLocale(tag) {
  return matchLocale(tag) ?? DEFAULT_LOCALE;
}

/** Best locale for the current environment: saved choice, then browser, then default. */
export function detectLocale() {
  if (typeof window === "undefined") return DEFAULT_LOCALE;

  try {
    const saved = window.localStorage?.getItem(STORAGE_KEY);
    if (saved && SUPPORTED_LOCALES.includes(saved)) return saved;
  } catch {
    // localStorage can throw in private mode / sandboxed iframes.
  }

  const tags = window.navigator?.languages?.length
    ? window.navigator.languages
    : [window.navigator?.language];

  for (const tag of tags) {
    const match = matchLocale(tag);
    if (match) return match;
  }
  return DEFAULT_LOCALE;
}

export default {
  "nav.dashboard": "Tableau de bord",
  "nav.tasks": "Tâches",

  "home.greeting": "Bon retour, {{name}}",
  // French treats 0 as singular, so `one` covers both 0 and 1.
  "home.tasksDue_one": "Vous avez {{count}} tâche à faire aujourd'hui.",
  "home.tasksDue_other": "Vous avez {{count}} tâches à faire aujourd'hui.",

  "actions.addTask": "Ajouter une tâche",
  "settings.emailUpdates": "M'envoyer les actualités par e-mail",

  "localeSwitcher.label": "Langue",
};

import { DEFAULT_LOCALE, LOCALES } from "./config.js";

const pluralRulesCache = new Map();

function getPluralRules(locale) {
  let rules = pluralRulesCache.get(locale);
  if (!rules) {
    rules = new Intl.PluralRules(locale);
    pluralRulesCache.set(locale, rules);
  }
  return rules;
}

/**
 * Candidate keys for a message, most specific first.
 * `count` selects a CLDR plural category (`_one`, `_other`, ...); an explicit
 * `_zero` entry wins at count 0 even in languages whose CLDR rules lack it.
 */
function keyCandidates(key, locale, count) {
  if (count === undefined || count === null) return [key];

  const candidates = [];
  if (count === 0) candidates.push(`${key}_zero`);
  candidates.push(`${key}_${getPluralRules(locale).select(count)}`);
  candidates.push(`${key}_other`, key);
  return candidates;
}

function lookup(locale, key, count) {
  for (const candidate of keyCandidates(key, locale, count)) {
    const message = LOCALES[locale]?.messages?.[candidate];
    if (typeof message === "string") return message;
  }
  return undefined;
}

/** Replace `{{name}}` placeholders, formatting numbers for the locale. */
function interpolate(message, locale, values) {
  return message.replace(/\{\{\s*(\w+)\s*\}\}/g, (match, name) => {
    if (!Object.hasOwn(values, name)) return match;
    const value = values[name];
    return typeof value === "number"
      ? new Intl.NumberFormat(locale).format(value)
      : String(value);
  });
}

/**
 * Translate `key` into `locale`.
 *
 * Falls back to DEFAULT_LOCALE for missing translations, then to the key
 * itself so the UI still renders something recognisable.
 */
export function translate(locale, key, values = {}) {
  const { count } = values;

  const message =
    lookup(locale, key, count) ??
    (locale === DEFAULT_LOCALE ? undefined : lookup(DEFAULT_LOCALE, key, count));

  if (message === undefined) {
    if (typeof process === "undefined" || process.env?.NODE_ENV !== "production") {
      console.warn(`[i18n] missing translation for "${key}" (${locale})`);
    }
    return key;
  }

  return interpolate(message, locale, values);
}

