/**
 * Pseudo-translate the source KLF catalog into a `qps` target locale.
 *
 * Readiness gate: accents and pads every translatable text run while leaving
 * placeholders (`ph`) and inline markup (`pcOpen`/`pcClose`) untouched. Any
 * string that still renders as plain English in the qps build is a string the
 * extractor never saw — i.e. still hardcoded.
 *
 * Stand-in for `kapi pseudo-translate i18n/ --target-lang qps`, which this
 * kapi build can't run (it reads KBF; the extractor emits KLF).
 */
import { readFileSync, writeFileSync, mkdirSync, readdirSync, statSync } from "node:fs";
import { join, extname, relative, dirname } from "node:path";

const ACCENTS = {
  a: "á", b: "b́", c: "ć", d: "d́", e: "é", f: "f́", g: "ǵ", h: "h́", i: "í",
  j: "j́", k: "favorite", l: "ĺ", m: "ḿ", n: "ń", o: "ó", p: "ṕ", q: "q́", r: "ŕ",
  s: "ś", t: "t́", u: "ú", v: "v́", w: "ẃ", x: "x́", y: "ý", z: "ź",
  A: "Á", B: "B́", C: "Ć", D: "D́", E: "É", F: "F́", G: "Ǵ", H: "H́", I: "Í",
  J: "J́", K: "favorite", L: "Ĺ", M: "Ḿ", N: "Ń", O: "Ó", P: "Ṕ", Q: "Q́", R: "Ŕ",
  S: "Ś", T: "T́", U: "Ú", V: "V́", W: "Ẃ", X: "X́", Y: "Ý", Z: "Ź",
};

const accent = (s) => [...s].map((ch) => ACCENTS[ch] ?? ch).join("");

/** Pad ~30% to surface truncation, mirroring kapi's pseudo-translate. */
function pad(s) {
  const letters = (s.match(/\p{L}/gu) ?? []).length;
  if (letters === 0) return s;
  return s + "·".repeat(Math.max(1, Math.round(letters * 0.3)));
}

const pseudoRuns = (runs) =>
  runs.map((run) => ("text" in run ? { ...run, text: pad(accent(run.text)) } : run));

function walk(dir, out = []) {
  for (const e of readdirSync(dir, { withFileTypes: true })) {
    const p = join(dir, e.name);
    if (e.isDirectory()) walk(p, out);
    else if (e.isFile() && extname(p) === ".klf") out.push(p);
  }
  return out;
}

const SRC_DIR = "i18n/src";
const OUT_DIR = "i18n/qps";
let blocks = 0;

for (const path of walk(SRC_DIR)) {
  const file = JSON.parse(readFileSync(path, "utf-8"));
  for (const doc of file.documents ?? []) {
    for (const block of doc.blocks ?? []) {
      if (!block.translatable) continue;
      block.targets = { ...block.targets, qps: pseudoRuns(block.source) };
      blocks++;
    }
  }
  const outPath = join(OUT_DIR, relative(SRC_DIR, path));
  mkdirSync(dirname(outPath), { recursive: true });
  writeFileSync(outPath, `${JSON.stringify(file, null, 2)}\n`);
}

console.log(`Pseudo-translated ${blocks} blocks → ${OUT_DIR}/`);

