import { createContext, useContext, useEffect, useMemo } from 'react';
import { createTranslator, detectLocales, directionOf, resolveLocale } from './translate.js';
import en from './messages/en.js';
import es from './messages/es.js';

export const DEFAULT_LOCALE = 'en';

// Register a locale by adding it here; every other layer reads from this map.
export const catalogs = { en, es };

export const supportedLocales = Object.keys(catalogs);

const I18nContext = createContext(null);

/**
 * Provides the active locale and `t` to the tree. Pass `locale` to force one
 * (a user setting, a route segment, a test); otherwise the browser's preferred
 * language is used, falling back to English.
 */
export function I18nProvider({ locale, children }) {
  const value = useMemo(() => {
    const active = resolveLocale(locale ?? detectLocales(), catalogs, DEFAULT_LOCALE);
    return {
      locale: active,
      dir: directionOf(active),
      t: createTranslator({ locale: active, catalogs, fallbackLocale: DEFAULT_LOCALE }),
    };
  }, [locale]);

  useEffect(() => {
    if (typeof document === 'undefined') return;
    document.documentElement.lang = value.locale;
    document.documentElement.dir = value.dir;
  }, [value.locale, value.dir]);

  return <I18nContext.Provider value={value}>{children}</I18nContext.Provider>;
}

/** Returns { t, locale, dir } for the nearest <I18nProvider>. */
export function useTranslation() {
  const context = useContext(I18nContext);
  if (!context) {
    throw new Error('useTranslation must be used inside an <I18nProvider>');
  }
  return context;
}

// Source of truth for UI copy. Keys are namespaced by feature.
// Placeholders use {name}; plural messages are objects keyed by CLDR category.
export default {
  'nav.dashboard': 'Dashboard',
  'nav.tasks': 'Tasks',

  'dashboard.greeting': 'Welcome back, {name}',
  'dashboard.tasksDueToday': {
    one: 'You have {count} task due today.',
    other: 'You have {count} tasks due today.',
  },

  'tasks.add': 'Add a task',

  'settings.emailUpdates': 'Email me about updates',
};

// Example locale. Keys missing here fall back to en.
export default {
  'nav.dashboard': 'Panel',
  'nav.tasks': 'Tareas',

  'dashboard.greeting': 'Hola de nuevo, {name}',
  'dashboard.tasksDueToday': {
    one: 'Tienes {count} tarea para hoy.',
    other: 'Tienes {count} tareas para hoy.',
  },

  'tasks.add': 'Añadir una tarea',

  'settings.emailUpdates': 'Quiero recibir novedades por correo',
};

// Pure translation core: no React, no imports, so it can be unit-tested and
// reused outside the component tree (emails, document titles, tests).

const RTL_LANGUAGES = new Set(['ar', 'arc', 'dv', 'fa', 'he', 'ku', 'ps', 'sd', 'ug', 'ur', 'yi']);
const PLACEHOLDER = /\{(\w+)\}/g;

const warned = new Set();

function warnOnce(message) {
  const isProduction = typeof process !== 'undefined' && process.env?.NODE_ENV === 'production';
  if (isProduction || warned.has(message)) return;
  warned.add(message);
  console.warn(`[i18n] ${message}`);
}

/**
 * Picks the best supported locale for a requested tag or list of tags,
 * falling back to the base language ("es-MX" -> "es") and then to the default.
 */
export function resolveLocale(requested, catalogs, defaultLocale) {
  const tags = requested == null ? [] : [].concat(requested);
  for (const tag of tags) {
    if (typeof tag !== 'string') continue;
    if (catalogs[tag]) return tag;
    const base = tag.split('-')[0];
    if (catalogs[base]) return base;
  }
  return defaultLocale;
}

/** Reads the browser's preferred languages, most-preferred first. */
export function detectLocales() {
  if (typeof navigator === 'undefined') return [];
  return navigator.languages?.length ? [...navigator.languages] : [navigator.language].filter(Boolean);
}

/** Writing direction for a locale, used for the <html dir> attribute. */
export function directionOf(locale) {
  try {
    const direction = new Intl.Locale(locale).textInfo?.direction;
    if (direction) return direction;
  } catch {
    // Intl.Locale#textInfo is not available everywhere; fall through to the list.
  }
  return RTL_LANGUAGES.has(locale.split('-')[0]) ? 'rtl' : 'ltr';
}

function interpolate(template, values, formatNumber) {
  return template.replace(PLACEHOLDER, (token, name) => {
    const value = values[name];
    if (value === undefined || value === null) {
      warnOnce(`no value supplied for "${name}" in "${template}"`);
      return token;
    }
    return typeof value === 'number' ? formatNumber(value) : String(value);
  });
}

/**
 * Builds a `t(key, values)` function bound to one locale.
 *
 * Messages are either a string ("Add a task"), or an object keyed by CLDR
 * plural category ({ one, other }) selected from `values.count`. Placeholders
 * are written as {name}; numbers are formatted for the active locale.
 */
export function createTranslator({ locale, catalogs, fallbackLocale }) {
  const pluralRules = new Intl.PluralRules(locale);
  const numberFormat = new Intl.NumberFormat(locale);
  const formatNumber = (value) => numberFormat.format(value);

  return function t(key, values = {}) {
    let message = catalogs[locale]?.[key];

    if (message === undefined) {
      message = catalogs[fallbackLocale]?.[key];
      if (message === undefined) {
        warnOnce(`missing message "${key}"`);
        return key;
      }
      warnOnce(`missing "${key}" for locale "${locale}", using ${fallbackLocale}`);
    }

    if (typeof message === 'object') {
      // Intl selects "other" for a missing or non-finite count, so a plural
      // message used without one degrades to the generic form instead of throwing.
      message = message[pluralRules.select(values.count)] ?? message.other;
      if (message === undefined) {
        warnOnce(`plural message "${key}" has no "other" form`);
        return key;
      }
    }

    return interpolate(message, values, formatNumber);
  };
}

